package category

import (
	"bytes"
	_ "embed" // Used by the embedded dataset, publisher rows and baseline model
	"fmt"

	"github.com/artifacthub/hub/internal/category/dataset"
	"github.com/artifacthub/hub/internal/category/model"
	"github.com/rs/zerolog/log"
)

// embeddedDataset represents the LLM labelled release dataset, packed with
// dataset.Pack. It's generated by the category train command.
//
//go:embed data/dataset.jsonl.gz
var embeddedDataset []byte

// embeddedPublisherRows represents the publisher rows the baseline model was
// trained on, packed with dataset.PackPublisherRows. It's generated by the
// category train command.
//
//go:embed data/publisher.jsonl.gz
var embeddedPublisherRows []byte

// embeddedBaseline represents the baseline model trained on the release
// dataset and the publisher rows. It's generated by the category train
// command.
//
//go:embed data/baseline.json
var embeddedBaseline []byte

// EmbeddedDataset returns the rows and the digest of the release dataset
// embedded in the binary.
func EmbeddedDataset() ([]dataset.Row, string, error) {
	rows, digest, err := dataset.ReadPacked(bytes.NewReader(embeddedDataset))
	if err != nil {
		return nil, "", fmt.Errorf("error reading dataset: %w", err)
	}
	return rows, digest, nil
}

// EmbeddedPublisherRows returns the rows and the digest of the publisher rows
// embedded in the binary.
func EmbeddedPublisherRows() ([]dataset.PublisherRow, string, error) {
	rows, digest, err := dataset.ReadPackedPublisherRows(bytes.NewReader(embeddedPublisherRows))
	if err != nil {
		return nil, "", fmt.Errorf("error reading publisher rows: %w", err)
	}
	return rows, digest, nil
}

// EmbeddedBaseline returns the baseline model embedded in the binary.
func EmbeddedBaseline() (*model.Model, error) {
	return model.Unmarshal(embeddedBaseline)
}

// NewEmbeddedClassifier creates a new Classifier instance using the baseline
// model embedded in the binary, logging which one it is. Its compatibility
// with the embedded dataset and the categories catalog is checked by the
// tests.
func NewEmbeddedClassifier() (*Classifier, error) {
	m, err := EmbeddedBaseline()
	if err != nil {
		return nil, fmt.Errorf("error loading embedded baseline model: %w", err)
	}
	log.Info().
		Str("algorithm", m.Algorithm).
		Str("training_set_digest", m.TrainingSetDigest).
		Str("dataset_digest", m.DatasetDigest).
		Msg("using embedded package category model")
	return NewClassifier(m)
}
